/**
 * The pieces of Python's `bytes` semantics that this program depends on:
 * `str.encode()` (UTF-8) and `repr(bytes)`.
 *
 * Both are reimplemented from their observable behaviour rather than delegated
 * to a Node built-in, because the details that matter here — which byte values
 * `repr` escapes, which quote character it picks — are precisely the details a
 * general-purpose helper would not preserve.
 */

import { PythonError } from './errors.mjs';

/** Counterpart of Python's `UnicodeEncodeError`. */
export class UnicodeEncodeError extends PythonError {
  /** @param {string} message exception message */
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/**
 * Encode a JavaScript string to UTF-8 bytes, the way `str.encode()` does.
 *
 * JavaScript strings are UTF-16, so astral characters arrive as surrogate
 * pairs and are recombined here.  An unpaired surrogate is not encodable as
 * UTF-8; Python refuses it rather than substituting a replacement character, so
 * this does too.
 *
 * @param {string} text the string to encode
 * @returns {Uint8Array} the UTF-8 bytes
 * @throws {UnicodeEncodeError} on an unpaired surrogate
 */
export function encodeUtf8(text) {
  const bytes = [];
  for (let i = 0; i < text.length; i += 1) {
    let codePoint = text.charCodeAt(i);

    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const low = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (low >= 0xdc00 && low <= 0xdfff) {
        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + (low - 0xdc00);
        i += 1;
      }
    }

    if (codePoint >= 0xd800 && codePoint <= 0xdfff) {
      const escaped = `\\u${codePoint.toString(16).padStart(4, '0')}`;
      throw new UnicodeEncodeError(
        `'utf-8' codec can't encode character '${escaped}' in position ${i}: ` +
          'surrogates not allowed',
      );
    }

    if (codePoint < 0x80) {
      bytes.push(codePoint);
    } else if (codePoint < 0x800) {
      bytes.push(0xc0 | (codePoint >> 6), 0x80 | (codePoint & 0x3f));
    } else if (codePoint < 0x10000) {
      bytes.push(
        0xe0 | (codePoint >> 12),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (codePoint >> 18),
        0x80 | ((codePoint >> 12) & 0x3f),
        0x80 | ((codePoint >> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    }
  }
  return Uint8Array.from(bytes);
}

const APOSTROPHE = 0x27;
const QUOTATION_MARK = 0x22;
const BACKSLASH = 0x5c;

/**
 * Escape sequences Python prefers over the generic `\xHH` form.  Note that
 * `\a`, `\b`, `\f`, `\v` and `\0` are deliberately absent: `repr` writes those
 * bytes as `\x07`, `\x08`, `\x0c`, `\x0b` and `\x00`.
 */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/**
 * Format bytes the way Python's `repr()` does, e.g. `b'\\x0c+2\\xbe'`.
 *
 * The quote character is chosen the way CPython chooses it: single quotes
 * normally, but double quotes when the data contains an apostrophe and no
 * quotation mark — so the apostrophe can be left unescaped.  When the data
 * contains both, single quotes win and the apostrophes are escaped.
 *
 * @param {Uint8Array} bytes the byte string
 * @returns {string} the Python `repr` of those bytes
 */
export function bytesRepr(bytes) {
  let hasApostrophe = false;
  let hasQuotationMark = false;
  for (const byte of bytes) {
    if (byte === APOSTROPHE) hasApostrophe = true;
    else if (byte === QUOTATION_MARK) hasQuotationMark = true;
  }

  const quote = hasApostrophe && !hasQuotationMark ? QUOTATION_MARK : APOSTROPHE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      body += `\\${String.fromCharCode(byte)}`;
      continue;
    }
    const shortEscape = SHORT_ESCAPES.get(byte);
    if (shortEscape !== undefined) {
      body += shortEscape;
    } else if (byte < 0x20 || byte >= 0x7f) {
      body += `\\x${byte.toString(16).padStart(2, '0')}`;
    } else {
      body += String.fromCharCode(byte);
    }
  }

  return `b${quoteChar}${body}${quoteChar}`;
}

/**
 * Cipher Block Chaining mode.
 *
 * Each plaintext block is XORed with the previous ciphertext block before
 * being enciphered; the initialisation vector seeds the chain.  The chaining
 * value is instance state, so feeding a message through successive `encrypt`
 * calls one block at a time produces the same ciphertext as encrypting it in
 * one go.  No padding is applied — every call must supply a whole block.
 */

import { AES, BLOCK_SIZE } from '../block-cipher.mjs';
import { ValueError, withPyFrames } from '../../python/errors.mjs';

/**
 * Source locations inside the reference `pyaes/aes.py` that each failure
 * corresponds to.  They exist only so the CLI can reproduce the reference
 * program's traceback verbatim.
 */
const PY_FRAMES = {
  ivSize: [
    ['pyaes/aes.py', 381, '__init__'],
  ],
  keySize: [
    ['pyaes/aes.py', 385, '__init__'],
    ['pyaes/aes.py', 304, '__init__'],
    ['pyaes/aes.py', 134, '__init__'],
  ],
  blockSize: [
    ['pyaes/aes.py', 389, 'encrypt'],
  ],
};

/** AES in CBC mode, operating one block at a time and chaining across calls. */
export class AESModeOfOperationCBC {
  /** Human-readable mode name, mirroring the reference library. */
  static modeName = 'Cipher-Block Chaining (CBC)';

  /** Whether this mode consumes fixed-size blocks rather than a byte stream. */
  static blockMode = true;

  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   * @param {Uint8Array} [iv] 16-byte initialisation vector; all-zero if omitted
   */
  constructor(key, iv) {
    // The initialisation vector is validated before the key, so a call that
    // gets both wrong reports the IV.
    if (iv === undefined || iv === null) {
      this.lastCipherblock = new Uint8Array(BLOCK_SIZE);
    } else if (iv.length !== BLOCK_SIZE) {
      throw withPyFrames(
        new ValueError('initialization vector must be 16 bytes'),
        PY_FRAMES.ivSize,
      );
    } else {
      this.lastCipherblock = Uint8Array.from(iv);
    }

    try {
      /** @type {AES} */
      this.aes = new AES(key);
    } catch (error) {
      throw withPyFrames(error, PY_FRAMES.keySize);
    }
  }

  /**
   * Encipher one block and advance the chain.
   *
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} 16 ciphertext bytes
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw withPyFrames(
        new ValueError('plaintext block must be 16 bytes'),
        PY_FRAMES.blockSize,
      );
    }
    const xored = new Uint8Array(BLOCK_SIZE);
    for (let i = 0; i < BLOCK_SIZE; i += 1) {
      xored[i] = plaintext[i] ^ this.lastCipherblock[i];
    }
    const ciphertext = this.aes.encryptBlock(xored);
    this.lastCipherblock = ciphertext;
    return ciphertext;
  }

  /**
   * Decipher one block and advance the chain.
   *
   * @param {Uint8Array} ciphertext exactly 16 bytes
   * @returns {Uint8Array} 16 plaintext bytes
   */
  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new ValueError('ciphertext block must be 16 bytes');
    }
    const decrypted = this.aes.decryptBlock(ciphertext);
    const plaintext = new Uint8Array(BLOCK_SIZE);
    for (let i = 0; i < BLOCK_SIZE; i += 1) {
      plaintext[i] = decrypted[i] ^ this.lastCipherblock[i];
    }
    this.lastCipherblock = Uint8Array.from(ciphertext);
    return plaintext;
  }
}
=== BLOCK ===
/**
 * The AES block cipher itself (FIPS-197): a keyed permutation on 16-byte
 * blocks, with no notion of chaining, padding or streams.  Modes of operation
 * live in `./modes/`.
 *
 * The state is held as a flat 16-byte array in column-major order, matching the
 * byte order of the plaintext: byte `i` sits at row `i % 4`, column
 * `Math.floor(i / 4)`.
 */

import { INV_SBOX, SBOX } from './tables.mjs';
import { gmul, xtime } from './galois.mjs';
import { expandKey } from './key-schedule.mjs';
import { ValueError } from '../python/errors.mjs';

/** AES block size in bytes. */
export const BLOCK_SIZE = 16;

/**
 * XOR the round key starting at `offset` bytes into the state.
 *
 * @param {Uint8Array} state 16-byte state
 * @param {Uint8Array} roundKeys expanded key
 * @param {number} round round index
 */
function addRoundKey(state, roundKeys, round) {
  const offset = round * BLOCK_SIZE;
  for (let i = 0; i < BLOCK_SIZE; i += 1) {
    state[i] ^= roundKeys[offset + i];
  }
}

/**
 * Apply the given substitution box to every byte of the state.
 *
 * @param {Uint8Array} state 16-byte state
 * @param {Uint8Array} box substitution table
 */
function subBytes(state, box) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) {
    state[i] = box[state[i]];
  }
}

/**
 * Rotate row `r` of the state left by `r` positions.
 *
 * @param {Uint8Array} state 16-byte state
 */
function shiftRows(state) {
  const source = state.slice();
  for (let column = 0; column < 4; column += 1) {
    for (let row = 0; row < 4; row += 1) {
      state[column * 4 + row] = source[((column + row) % 4) * 4 + row];
    }
  }
}

/**
 * Rotate row `r` of the state right by `r` positions.
 *
 * @param {Uint8Array} state 16-byte state
 */
function invShiftRows(state) {
  const source = state.slice();
  for (let column = 0; column < 4; column += 1) {
    for (let row = 0; row < 4; row += 1) {
      state[column * 4 + row] = source[((column - row + 4) % 4) * 4 + row];
    }
  }
}

/**
 * Multiply each column of the state by the fixed MixColumns matrix.
 *
 * @param {Uint8Array} state 16-byte state
 */
function mixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const base = column * 4;
    const a0 = state[base];
    const a1 = state[base + 1];
    const a2 = state[base + 2];
    const a3 = state[base + 3];
    const parity = a0 ^ a1 ^ a2 ^ a3;
    state[base] = a0 ^ parity ^ xtime(a0 ^ a1);
    state[base + 1] = a1 ^ parity ^ xtime(a1 ^ a2);
    state[base + 2] = a2 ^ parity ^ xtime(a2 ^ a3);
    state[base + 3] = a3 ^ parity ^ xtime(a3 ^ a0);
  }
}

/**
 * Multiply each column of the state by the inverse MixColumns matrix.
 *
 * @param {Uint8Array} state 16-byte state
 */
function invMixColumns(state) {
  for (let column = 0; column < 4; column += 1) {
    const base = column * 4;
    const a0 = state[base];
    const a1 = state[base + 1];
    const a2 = state[base + 2];
    const a3 = state[base + 3];
    state[base] = gmul(a0, 14) ^ gmul(a1, 11) ^ gmul(a2, 13) ^ gmul(a3, 9);
    state[base + 1] = gmul(a0, 9) ^ gmul(a1, 14) ^ gmul(a2, 11) ^ gmul(a3, 13);
    state[base + 2] = gmul(a0, 13) ^ gmul(a1, 9) ^ gmul(a2, 14) ^ gmul(a3, 11);
    state[base + 3] = gmul(a0, 11) ^ gmul(a1, 13) ^ gmul(a2, 9) ^ gmul(a3, 14);
  }
}

/**
 * Raw AES: a single-block encrypt/decrypt primitive for a 128, 192 or 256 bit
 * key.  Rejecting a wrong-sized key with `ValueError('Invalid key size')`
 * mirrors the reference library.
 */
export class AES {
  /**
   * @param {Uint8Array} key 16, 24 or 32 raw key bytes
   */
  constructor(key) {
    const { words, rounds } = expandKey(key);
    /** @type {Uint8Array} expanded round keys */
    this.roundKeys = words;
    /** @type {number} number of cipher rounds */
