/**
 * Differential harness: reference PyInstaller binary vs the Node ESM port.
 * Compares stdout bytes, normalised stderr and exit code.
 */
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test17_executable';
const PORT_ARGS = ['/output/test17.mjs'];

const normErr = (buf) =>
  buf.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function runRaw(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], {
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, PYTHONIOENCODING: undefined },
  });
  return {
    out: r.stdout ?? Buffer.alloc(0),
    err: r.stderr ?? Buffer.alloc(0),
    code: r.status,
    signal: r.signal,
  };
}

/** The reference binary is flaky under load; retry a null/signal exit. */
function runRef(argv) {
  let last;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    last = runRaw(REF, [], argv);
    if (last.code !== null) return last;
  }
  return last;
}

const runPort = (argv) => runRaw(process.execPath, PORT_ARGS, argv);

const results = [];

/** Compare one invocation; retries the reference on any mismatch. */
export function check(name, argv, meta = {}) {
  let ref = runRef(argv);
  let port = runPort(argv);
  let diff = describeDiff(ref, port);

  // Re-run the exact same reference command 3 times before believing a failure.
  if (diff) {
    for (let attempt = 0; attempt < 3 && diff; attempt += 1) {
      ref = runRef(argv);
      diff = describeDiff(ref, port);
    }
  }

  const row = {
    name,
    ...meta,
    refCode: ref.code,
    portCode: port.code,
    refSignal: ref.signal,
    outBytes: ref.out.length,
    portOutBytes: port.out.length,
    outLines: ref.out.length === 0 ? 0 : ref.out.toString('utf8').split('\n').length - 1,
    refErrFirstLine: normErr(ref.err).split('\n').filter(Boolean).slice(-2, -1)[0] ?? '',
    ok: !diff,
    diff,
  };
  results.push(row);
  return row;
}

function describeDiff(ref, port) {
  const problems = [];
  if (ref.code !== port.code) problems.push(`exit ${ref.code} vs ${port.code}`);
  if (!ref.out.equals(port.out)) {
    problems.push(
      `stdout differs (ref ${ref.out.length}B, port ${port.out.length}B)\n` +
        `  REF : ${JSON.stringify(ref.out.toString('utf8').slice(0, 600))}\n` +
        `  PORT: ${JSON.stringify(port.out.toString('utf8').slice(0, 600))}`,
    );
  }
  const re = normErr(ref.err);
  const pe = normErr(port.err);
  if (re !== pe) {
    problems.push(
      `stderr differs\n  REF :\n${re.replace(/^/gm, '    ')}\n  PORT:\n${pe.replace(/^/gm, '    ')}`,
    );
  }
  return problems.length ? problems.join('\n') : null;
}

export function report(title) {
  const bad = results.filter((r) => !r.ok);
  console.log(`\n#### ${title}`);
  console.log('| case | exit(ref/port) | stdout lines | stdout bytes | last stderr line | match |');
  console.log('|---|---|---|---|---|---|');
  for (const r of results) {
    console.log(
      `| ${r.name} | ${r.refCode}/${r.portCode} | ${r.outLines} | ${r.outBytes} | ${r.refErrFirstLine.slice(0, 70)} | ${r.ok ? 'OK' : '**MISMATCH**'} |`,
    );
  }
  console.log(`\nTOTAL ${results.length}, mismatches ${bad.length}`);
  for (const r of bad) {
    console.log(`\n=== MISMATCH: ${r.name}\nargv-meta: ${JSON.stringify(r)}\n${r.diff}`);
  }
  return bad.length;
}

